#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int best = 0, i = 0, left = 0, m = 0, n = 0, need = 0, right = 0, start = 0, x = 0;
    // 读取 s 和 t；a/b 是字符数据，d/e 分别保存需求与窗口次数。
    n = readstr(a);
    m = readstr(b);
    for (i = 0; i < m; i += 1) {
        d[b[i]] = (d[b[i]] + 1);
    }
    left = 0;
    // need 是缺少的字符总个数，目标中的重复字符也逐个计入。
    need = m;
    best = (n + 1);
    start = 0;
    for (right = 0; right < n; right += 1) {
        x = a[right];
        if (e[x] < d[x]) {
            need = (need - 1);
        }
        e[x] = (e[x] + 1);
        // 覆盖完整后先记录答案再删左端，直到刚好缺少所需字符。
        while ((need == 0) && (left <= right)) {
            if (((right - left) + 1) < best) {
                best = ((right - left) + 1);
                start = left;
            }
            x = a[left];
            e[x] = (e[x] - 1);
            if (e[x] < d[x]) {
                need = (need + 1);
            }
            left = (left + 1);
        }
    }
    // 空目标或无解按平台约定输出 -，否则输出最短最早子串。
    if ((m == 0) || (best == (n + 1))) {
        emitstr(b, 0);
    }
    else {
        for (i = 0; i < best; i += 1) {
            b[i] = a[(start + i)];
        }
        emitstr(b, best);
    }
    return 0;
}

