use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut best: i32 = 0;
    let mut i: i32 = 0;
    let mut left: i32 = 0;
    let mut m: i32 = 0;
    let mut n: i32 = 0;
    let mut need: i32 = 0;
    let mut right: i32 = 0;
    let mut start: i32 = 0;
    let mut x: i32 = 0;
    // 读取 s 和 t；a/b 是字符数据，d/e 分别保存需求与窗口次数。
    n = reader.readstr(&mut a);
    m = reader.readstr(&mut b);
    i = 0;
    while i < m {
        d[(b[(i) as usize]) as usize] = (d[(b[(i) as usize]) as usize] + 1);
        i += 1;
    }
    left = 0;
    // need 是缺少的字符总个数，目标中的重复字符也逐个计入。
    need = m;
    best = (n + 1);
    start = 0;
    right = 0;
    while right < n {
        x = a[(right) as usize];
        if (e[(x) as usize] < d[(x) as usize]) {
            need = (need - 1);
        }
        e[(x) as usize] = (e[(x) as usize] + 1);
        // 覆盖完整后先记录答案再删左端，直到刚好缺少所需字符。
        while ((need == 0) && (left <= right)) {
            if (((right - left) + 1) < best) {
                best = ((right - left) + 1);
                start = left;
            }
            x = a[(left) as usize];
            e[(x) as usize] = (e[(x) as usize] - 1);
            if (e[(x) as usize] < d[(x) as usize]) {
                need = (need + 1);
            }
            left = (left + 1);
        }
        right += 1;
    }
    // 空目标或无解按平台约定输出 -，否则输出最短最早子串。
    if ((m == 0) || (best == (n + 1))) {
        emitstr(&b, 0);
    } else {
        i = 0;
        while i < best {
            b[(i) as usize] = a[(start + i) as usize];
            i += 1;
        }
        emitstr(&b, best);
    }
}
